import json
import os
import sys
from unified_planning.io import PDDLReader
from unified_planning.shortcuts import OneshotPlanner

def solve_tasks():
    try:
        with open("problem.json", "r") as f:
            tasks = json.load(f)
    except FileNotFoundError:
        print("problem.json not found.")
        return

    reader = PDDLReader()

    for task in tasks:
        domain_path = task.get("domain")
        problem_path = task.get("problem")
        output_path = task.get("plan_output")

        if not domain_path or not problem_path or not output_path:
            print(f"Skipping task {task.get('id', 'unknown')}: Missing paths")
            continue

        print(f"Processing task: {task.get('id')}")
        print(f"  Domain: {domain_path}")
        print(f"  Problem: {problem_path}")

        try:
            problem = reader.parse_problem(domain_path, problem_path)
        except Exception as e:
            print(f"  Error parsing problem: {e}")
            continue

        print("  Solving...")
        try:
            with OneshotPlanner(name="pyperplan") as planner:
                result = planner.solve(problem)
        except Exception as e:
            print(f"  Error during planning: {e}")
            continue

        if result.status.name in ["SOLVED_SATISFICING", "SOLVED_OPTIMALLY"]:
            plan = result.plan
            print(f"  Plan found. Writing to {output_path}")

            # Write plan
            try:
                os.makedirs(os.path.dirname(output_path) if os.path.dirname(output_path) else '.', exist_ok=True)
                with open(output_path, "w") as f:
                    if plan:
                        for action in plan.actions:
                            f.write(str(action) + "\n")
            except Exception as e:
                print(f"  Error writing plan: {e}")
        else:
            print(f"  No plan found. Status: {result.status.name}")

if __name__ == "__main__":
    solve_tasks()

